// n8n Code node "Check cache" (Run Once for All Items)
// First step after the webhook. Holds the config, splits the batch into SOS notes HQ has
// already answered (cached) and new ones (fresh). This is the cross-run de-duplication (FIXES F7):
// the same SOS can arrive in two vans' batches, or be resent after a timeout, and is handled once.
// The cache lives in n8n's workflow static data, which persists between PRODUCTION executions
// (workflow active, called on /webhook/sos), not between manual test runs.

// ---- Config: edit these ----
const CONFIG = {
  simBase: 'http://localhost:8000/',          // where the sim serves SOS audio (relative `audio` paths resolve here)
  elevenBase: 'https://api.elevenlabs.io',
  anthropicBase: 'https://api.anthropic.com',
  claudeModel: 'claude-opus-5-5',
  claudeEffort: 'low',                         // fast triage; raise to 'medium' if replies look weak
  voiceId: 'JBFqnCBsd6RMkjVDRZzb',             // any ElevenLabs voice id; pick one that sounds good in Arabic/Urdu
  ttsModel: 'eleven_multilingual_v2',
  slackWebhookUrl: '',                         // optional Slack incoming-webhook URL for urgent SOS alerts
};
// ----------------------------

const body = $input.first().json.body || {};
const batch = Array.isArray(body.batch) ? body.batch : [];

const store = $getWorkflowStaticData('global');
store.replies = store.replies || {};

const fresh = [];
const cached = [];
const seen = new Set();
for (const sos of batch) {
  if (!sos || !sos.sos_id || seen.has(sos.sos_id)) continue;
  seen.add(sos.sos_id);
  if (store.replies[sos.sos_id]) cached.push(store.replies[sos.sos_id]);
  else fresh.push(sos);
}

return [{ json: { cfg: CONFIG, van: body.van ?? null, t: body.t ?? null, fresh, cached } }];

// n8n Code node "One item per SOS" (Run Once for All Items)
// Turns the fresh SOS list into one n8n item each, with an absolute audio URL to download.

const { cfg, fresh } = $input.first().json;

function toUrl(audio, base) {
  if (!audio) return '';
  if (/^https?:\/\//.test(audio)) return audio;
  return base.replace(/\/+$/, '') + '/' + String(audio).replace(/^\/+/, '');
}

return fresh.map(sos => ({
  json: {
    sos_id: sos.sos_id,
    household: sos.household,
    lang: sos.lang || null,
    text: sos.text || null,
    audio_url: toUrl(sos.audio, cfg.simBase),
  },
}));

// n8n Code node "Pick transcript" (Run Once for Each Item)
// Takes ElevenLabs Scribe's transcript, or falls back to the SOS's own text if there was no audio
// or transcription failed. Builds the Claude request for the next node.

const sos = $('One item per SOS').item.json;
const cfg = $('Check cache').first().json.cfg;
const stt = $json || {};

const sttText = typeof stt.text === 'string' ? stt.text.trim() : '';
const transcript = sttText || (sos.text || '').trim();
const lang = stt.language_code || sos.lang || 'en';
const ok = transcript.length > 0;
const sttError = stt.error ? String(stt.error.message || stt.error) : null;

const system = [
  'You triage voice SOS messages for a flood-relief operation whose radios and phones are down.',
  "Each message was recorded on an aid van's device when the van delivered rations to a household,",
  'and carried back to HQ. The transcript may be in any language. Return:',
  '- english: a faithful English translation.',
  '- needs: short list of concrete needs, e.g. "insulin", "baby formula", "drinking water". Empty if none.',
  '- urgency: 3 if life-threatening or medical (medication, injury, infant, pregnant, elderly person alone),',
  '  2 if important but not life-threatening, 1 otherwise.',
  '- people: number of people mentioned, or 0 if unknown.',
  '- reply: a short spoken reply to the household in the language of the transcript, at most two sentences,',
  '  warm and plain. Confirm what HQ understood and that it will go out with the next van.',
  '  Never promise a specific time, van or item.',
  '- reply_lang: ISO 639-1 code of the reply language.',
].join('\n');

const schema = {
  type: 'object',
  properties: {
    english: { type: 'string' },
    needs: { type: 'array', items: { type: 'string' } },
    urgency: { type: 'integer' },
    people: { type: 'integer' },
    reply: { type: 'string' },
    reply_lang: { type: 'string' },
  },
  required: ['english', 'needs', 'urgency', 'people', 'reply', 'reply_lang'],
  additionalProperties: false,
};

const claudeRequest = {
  model: cfg.claudeModel,
  max_tokens: 4000,
  fallbacks: 'default',
  output_config: { effort: cfg.claudeEffort, format: { type: 'json_schema', schema } },
  system,
  messages: [{
    role: 'user',
    content: `Household: ${sos.household}\nLanguage detected by speech recognition: ${lang}\nTranscript:\n"""\n${transcript}\n"""`,
  }],
};

return { json: { sos, transcript, lang, ok, sttError, claudeRequest } };

// n8n Code node "Parse triage" (Run Once for Each Item)
// Reads Claude's JSON answer. If Claude failed or declined, falls back to a fixed reply in the
// household's language so the household still hears something (marked degraded).

const prev = $('Pick transcript').item.json;
const cfg = $('Check cache').first().json.cfg;
const res = $json || {};

const FALLBACK_REPLY = {
  en: 'Your message reached HQ. Help will come with the next van.',
  ar: 'وصلت رسالتك إلى المقر. ستصل المساعدة مع الشاحنة التالية.',
  ur: 'آپ کا پیغام ہیڈکوارٹر تک پہنچ گیا ہے۔ اگلی وین کے ساتھ مدد پہنچے گی۔',
};

let triage = null;
let claudeError = null;
if (prev.ok) {
  try {
    if (res.error) throw new Error(String(res.error.message || JSON.stringify(res.error)));
    if (res.stop_reason === 'refusal') throw new Error('Claude declined the request');
    const textBlock = (res.content || []).find(b => b.type === 'text');
    if (!textBlock) throw new Error('No text block in Claude response');
    triage = JSON.parse(textBlock.text);
  } catch (err) {
    claudeError = String(err.message || err);
  }
}

const lang2 = String(prev.lang || 'en').slice(0, 2).toLowerCase();
const degraded = !triage;
if (!triage) {
  triage = {
    english: prev.transcript,
    needs: [],
    urgency: 2,
    people: 0,
    reply: FALLBACK_REPLY[lang2] || FALLBACK_REPLY.en,
    reply_lang: FALLBACK_REPLY[lang2] ? lang2 : 'en',
  };
}

return {
  json: {
    sos: prev.sos,
    ok: prev.ok,
    transcript: prev.transcript,
    lang: prev.lang,
    triage,
    degraded,
    errors: { stt: prev.sttError, claude: claudeError },
    ttsRequest: { text: triage.reply, model_id: cfg.ttsModel },
  },
};

// n8n Code node "Build replies" (Run Once for All Items)
// Joins each triaged SOS with its spoken reply (base64 MP3), caches successful replies so a resent
// SOS is answered without reprocessing, and builds the webhook response.
// If any SOS could not be transcribed, answers 503 so the sim's hq_link keeps the batch and retries;
// the ones that worked are cached, so the retry only redoes the failures.

const head = $('Check cache').first().json;
const triaged = $('Parse triage').all();
const tts = $input.all();

const store = $getWorkflowStaticData('global');
store.replies = store.replies || {};

const replies = [...head.cached];
const failed = [];
const urgent = [];

for (let i = 0; i < triaged.length; i++) {
  const p = triaged[i].json;
  if (!p.ok) {
    failed.push({ sos_id: p.sos.sos_id, why: p.errors.stt || 'no audio and no text' });
    continue;
  }
  let audio_b64 = null;
  const item = tts[i];
  if (item && item.binary && item.binary.data) {
    try {
      audio_b64 = (await this.helpers.getBinaryDataBuffer(i, 'data')).toString('base64');
    } catch (err) {
      audio_b64 = null; // reply still goes out as text
    }
  }
  const reply = {
    sos_id: p.sos.sos_id,
    household: p.sos.household,
    lang: p.triage.reply_lang || p.lang,
    text: p.triage.reply,
    audio_b64,
    mime: 'audio/mpeg',
    english: p.triage.english,
    needs: p.triage.needs,
    urgency: p.triage.urgency,
    degraded: p.degraded,
  };
  store.replies[reply.sos_id] = reply;
  replies.push(reply);
  if (reply.urgency >= 3) urgent.push(reply);
}

const status = failed.length ? 503 : 200;
const response = failed.length
  ? { error: 'Some SOS notes could not be transcribed; resend the batch later.', failed, replies }
  : { replies };

return [{ json: { status, response, urgent, slack: head.cfg.slackWebhookUrl, van: head.van, t: head.t } }];

// n8n Code node "Cached replies only" (Run Once for All Items)
// Every SOS in the batch was already answered: return the stored replies without calling any API.

const { cached } = $input.first().json;
return [{ json: { status: 200, response: { replies: cached }, urgent: [], slack: '' } }];
